style.css:
@-moz-document domain("roblox.com") {
/* Fundo geral do site com a imagem enviada */
  body, #app, .app-container, .container-fluid {
    background-image: linear-gradient(rgba(10, 8, 20, 0.75), rgba(10, 8, 20, 0.75)),
      url("data:image/webp;base64,") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* Deixa os cards e painéis com fundo semi-transparente pra combinar */
  .game-card, .container-list, .navbar-container, #header, .rbx-navbar {
    background-color: rgba(20, 15, 35, 0.55) !important;
    backdrop-filter: blur(4px);
  }

  /* Textos com um tom mais claro pra manter legibilidade */
  .text-header, .font-header-2, .text-label, h1, h2, h3 {
    color: #f5eefc !important;
  }

  /* Barra de navegação superior */
  .navbar-container {
    border-bottom: 1px solid rgba(200, 170, 220, 0.4) !important;
  }

  /* Scrollbar combinando com o tema */
  ::-webkit-scrollbar-thumb {
    background-color: #8a6ea8 !important;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background-color: rgba(10, 8, 20, 0.6) !important;
  }
}
